const items = $input.all();
const batch = items[0].json.body.items || items[0].json.body.data || [];

// Prepare items for classification
const preparedItems = batch.map((item, i) => ({
  index: i,
  text: typeof item === 'string' ? item : item.text || item.description || item.content || JSON.stringify(item),
  original: item
}));

// Split into chunks of 10 for API efficiency
const chunks = [];
for (let i = 0; i < preparedItems.length; i += 10) {
  chunks.push(preparedItems.slice(i, i + 10));
}

return chunks.map(chunk => ({
  json: {
    items: chunk,
    categories: items[0].json.body.categories || ['Technology', 'Business', 'Science', 'Health', 'Education', 'Other'],
    batchSize: chunk.length
  }
}));

