const items = $input.all();
const categorized = {};

for (const item of items) {
  let classifications;
  try {
    const content = item.json.message.content;
    const jsonMatch = content.match(/\[.*\]/s);
    classifications = jsonMatch ? JSON.parse(jsonMatch[0]) : [];
  } catch (e) {
    classifications = [];
  }

  for (const cls of classifications) {
    const category = cls.category || 'Uncategorized';
    if (!categorized[category]) categorized[category] = [];
    categorized[category].push({
      text: cls.text || `Item ${cls.index}`,
      confidence: cls.confidence || 0,
      reason: cls.reason || ''
    });
  }
}

const summary = Object.entries(categorized).map(([category, items]) => ({
  category,
  count: items.length,
  items
}));

return [{
  json: {
    totalItems: summary.reduce((a, c) => a + c.count, 0),
    categoryCount: summary.length,
    categories: summary,
    processedAt: new Date().toISOString()
  }
}];
